        else:
            raise ValueError('Invalid time format')
    # Check if the time is in 12-hour format
    elif ' ' in time_str:
        # Split the time into hours, minutes, and AM/PM
        hours, minutes, am_pm = time_str.split(' ')
        # Check if the hours, minutes, and AM/PM are valid
        if len(hours) == 2 and len(minutes) == 2 and (am_pm == 'AM' or am_pm == 'PM') and hours.isdigit() and minutes.isdigit():
