    string_2 = string_2.lower()

    # Check if input strings are alphanumeric
    if not string_1.isalnum() or not string_2.isalnum():
        raise ValueError("Input strings should be alphanumeric.")

    # Remove white spaces
    string_1 = string_1.replace(" ", "")
    string_2 = string_2.replace(" ", "")

    # Replace special characters with ASCII value of first character of second string
    for char in string_1:
