public String concatenateInteger(String str, int num) {
    if (num < 1 || num >= 1000) {
        throw new IllegalArgumentException("The integer must be positive and less than 1000.");
    }

    String numStr = String.valueOf(num);

    // Check if the number has any duplicate digits
    boolean[] visited = new boolean[10];
    for (char c : numStr.toCharArray()) {
        int digit = c - '0';
        if (visited[digit]) {
            throw new IllegalArgumentException("The integer should not contain any digit more than once.");
        }
        visited[digit] = true;
    }

    // Check if the digits are arranged in descending order
    for (int i = 0; i < numStr.length() - 1; i++) {
        if (numStr.charAt(i) <= numStr.charAt(i + 1)) {
            throw new IllegalArgumentException("The digits of the integer must be arranged in descending order.");
        }
    }

    return numStr + str;
}
