Here's the implementation of the DoublyLinkedList class with the additional operations:

```cpp
class DoublyLinkedList {
private:
    struct Node {
        int data;
        Node* prev;
        Node* next;

        Node(int value) : data(value), prev(nullptr), next(nullptr) {}
    };

    Node* head;
    Node* tail;
    int size;

public:
    DoublyLinkedList() {
        head = new Node(0);
        tail = new Node(0);
        head->next = tail;
        tail->prev = head;
        size = 0;
    }

    ~DoublyLinkedList() {
        clear();
        delete head;
        delete tail;
    }

    void insertFront(int value) {
        Node* newNode = new Node(value);
        newNode->prev = head;
        newNode->next = head->next;
        head->next->prev = newNode;
        head->next = newNode;
        size++;
    }

    void insertEnd(int value) {
        Node* newNode = new Node(value);
        newNode->next = tail;
        newNode->prev = tail->prev;
        tail->prev->next = newNode;
        tail->prev = newNode;
        size++;
    }

    void deleteNode(int value) {
        Node* curr = head->next;
        while (curr != tail) {
            if (curr->data == value) {
                curr->prev->next = curr->next;
                curr->next->prev = curr->prev;
                delete curr;
                size--;
                return;
            }
            curr = curr->next;
        }
    }

    void reverse() {
        Node* curr = head;
        Node* temp = nullptr;
        while (curr != nullptr) {
            temp = curr->prev;
            curr->prev = curr->next;
            curr->next = temp;
            curr = curr->prev;
        }
        if (temp != nullptr) {
            head = temp->prev;
        }
    }

    int getKthFromEnd(int k) {
        if (k > size) {
            return -1;
        }
        Node* curr = tail->prev;
        while (k > 1) {
            curr = curr->prev;
            k--;
        }
        return curr->data;
    }

    void sort() {
        mergeSort(head->next, tail->prev);
    }

    void mergeSort(Node* start, Node* end) {
        if (start != end) {
            Node* mid = getMiddle(start, end);
            mergeSort(start, mid);
            mergeSort(mid->next, end);
            merge(start, mid, end);
        }
    }

    Node* getMiddle(Node* start, Node* end) {
        Node* slow = start;
        Node* fast = start;
        while (fast != end && fast->next != end) {
            slow = slow->next;
            fast = fast->next->next;
        }
        return slow;
    }

    void merge(Node* start, Node* mid, Node* end) {
        DoublyLinkedList mergedList;
        Node* left = start;
        Node* right = mid->next;
        while (left != mid->next && right != end->next) {
            if (left->data <= right->data) {
                mergedList.insertEnd(left->data);
                left = left->next;
            } else {
                mergedList.insertEnd(right->data);
                right = right->next;
            }
        }
        while (left != mid->next) {
            mergedList.insertEnd(left->data);
            left = left->next;
        }
        while (right != end->next) {
            mergedList.insertEnd(right->data);
            right = right->next;
        }
        Node* curr = start;
        Node* mergedCurr = mergedList.head->next;
        while (curr != end->next) {
            curr->data = mergedCurr->data;
            curr = curr->next;
            mergedCurr = mergedCurr->next;
        }
    }

    DoublyLinkedList merge(DoublyLinkedList list) {
        DoublyLinkedList mergedList;
        Node* curr1 = head->next;
        Node* curr2 = list.head->next;
        while (curr1 != tail && curr2 != list.tail) {
            if (curr1->data <= curr2->data) {
                mergedList.insertEnd(curr1->data);
                curr1 = curr1->next;
            } else {
                mergedList.insertEnd(curr2->data);
                curr2 = curr2->next;
            }
        }
        while (curr1 != tail) {
            mergedList.insertEnd(curr1->data);
            curr1 = curr1->next;
        }
        while (curr2 != list.tail) {
            mergedList.insertEnd(curr2->data);
            curr2 = curr2->next;
        }
        return mergedList;
    }

    void print() {
        Node* curr = head->next;
        while (curr != tail) {
            cout << curr->data << " ";
            curr = curr->next;
        }
        cout << endl;
    }

    void clear() {
        Node* curr = head->next;
        while (curr != tail) {
            Node* temp = curr;
            curr = curr->next;
            delete temp;
        }
        head->next = tail;
        tail->prev = head;
        size = 0;
    }
};
```

